Q = [
    make(1, "下列哪一項最適合用來比較兩個物體的慣性大小？", {"A": "比較兩物體的質量", "B": "比較兩物體的顏色", "C": "比較兩物體的表面亮度", "D": "比較兩物體的形狀是否相似"}, "A", "質量是慣性大小的量度；質量越大，物體越抗拒運動狀態改變。顏色、亮度與外形不能直接決定慣性。", "先找能量化抗拒運動改變程度的物理量，再排除只描述外觀的線索。", ["辨認題目問的是慣性大小。", "慣性描述改變運動狀態的難易。", "質量越大通常越難改變運動狀態。", "顏色、亮度和形狀不是慣性的量度。", "因此應選比較質量的做法。"], "easy"),
    make(2, "兩輛原本都靜止的推車分別為 2 kg 與 6 kg；若受到相同水平合力作用相同時間，哪輛車的速度改變通常較大？", {"A": "6 kg 的推車，因為質量大", "B": "2 kg 的推車，因為質量小、慣性較小", "C": "兩輛一樣，質量不影響慣性", "D": "無法比較，因為推車原本靜止"}, "B", "同力同時間下，質量較小者的慣性較小，較容易改變速度，因此 2 kg 推車的速度改變通常較大。", "固定外力與作用時間，只比較質量；不要把較大的質量誤判為較容易加速。", ["確認兩車初始狀態相同，都是靜止。", "確認外力大小與作用時間相同。", "比較質量：2 kg 小於 6 kg。", "質量較小代表慣性較小，速度較容易改變。", "所以 2 kg 推車的速度改變較大。"], "easy"),
    make(3, "研究質量對速度改變的影響時，甲、乙物體質量不同，但施力大小、施力時間與初速度都相同。這樣的設計主要控制了哪些條件？", {"A": "只控制物體顏色", "B": "只控制物體體積", "C": "外力、作用時間與初始運動狀態", "D": "把質量也控制成相同"}, "C", "若要把質量作為主要變因，應固定外力、作用時間與初始狀態，才能把速度改變差異合理歸因於質量與慣性。", "列出自變因與應控制的條件，檢查是否只改變一個主要因素。", ["找出研究者想比較的因素：質量。", "其他會影響速度改變的條件應保持相同。", "外力大小必須相同。", "作用時間與初速度也必須相同。", "因此正確控制條件是外力、時間與初始狀態。"], "medium"),
    make(4, "同一地點有一個 3 kg 的籃球與一個 3 kg 的鉛球。若只根據慣性判斷，兩球的慣性大小如何？", {"A": "籃球較大，因為體積較大", "B": "鉛球較大，因為看起來較重", "C": "兩球相同，因為質量相同", "D": "無法判斷，因為材質不同"}, "C", "慣性大小主要由質量決定；兩球質量同為 3 kg，因此就慣性而言相同。重量、體積和材質不能在此改變質量比較的結論。", "把慣性判斷鎖定在質量，不被外觀、材質或體積帶走。", ["讀取兩球的質量，都是 3 kg。", "慣性大小以質量作主要判斷依據。", "體積與材質不是本題的慣性量度。", "因此兩球抗拒運動狀態改變的程度相同。", "所以選兩球慣性相同。"], "easy"),
    make(5, "一輛公車由靜止突然向前加速時，站立乘客的上半身較容易向後傾。下列解釋何者正確？", {"A": "乘客受到一個固定向後的慣性力", "B": "乘客的身體傾向維持原本靜止狀態，車身先向前移動", "C": "乘客質量突然變小", "D": "公車加速使重力方向改變"}, "B", "慣性不是額外的力；公車地板帶動腳部向前，身體其他部分傾向維持原來靜止狀態，因而相對車身呈現向後傾。", "先說清楚以車內為觀察情境，再分辨身體原本狀態與車身的新運動。", ["確認公車原本是靜止，接著向前加速。", "乘客身體原先也接近靜止。", "車身與腳部先被推向前。", "身體其他部分傾向維持原本狀態。", "相對公車看起來向後傾，這是慣性現象而非慣性力。"], "medium"),
    make(6, "下列哪一種證據最能支持『質量較大的物體慣性較大』？", {"A": "兩物體外觀大小不同，但沒有量測運動", "B": "在相同外力與時間下，質量較大者速度改變較小", "C": "質量較大者顏色較深", "D": "質量較大者放在較低的位置"}, "B", "控制外力與時間後，直接比較速度改變，才能把較小的速度改變與較大的慣性連結；其他選項沒有提供相關運動證據。", "優先選擇同條件、可量測、直接對應運動狀態改變的證據。", ["確認要驗證的是質量與慣性的關係。", "慣性需透過改變運動狀態的難易來觀察。", "固定外力與作用時間。", "比較兩物體速度改變的大小。", "質量較大且速度改變較小的結果最能支持該結論。"], "medium"),
    make(7, "一個 1 kg 物體與一個 4 kg 物體受到相同合力。若不考慮其他差異，哪個敘述較合理？", {"A": "1 kg 物體的慣性較大，速度改變較小", "B": "4 kg 物體的慣性較大，速度改變較小", "C": "兩物體慣性相同，因為受力相同", "D": "質量較大者一定靜止不動"}, "B", "質量 4 kg 較大，所以慣性較大；在相同合力下，較大的質量通常產生較小的加速度，也就是速度改變較小。", "分開判斷『受力相同』與『慣性大小』，不可把相同外力當成相同加速度。", ["比較兩物體質量，4 kg 大於 1 kg。", "質量較大表示慣性較大。", "相同合力作用時，大慣性較不易改變運動狀態。", "因此 4 kg 物體的速度改變通常較小。", "選出同時符合質量與運動改變關係的敘述。"], "medium"),
    make(8, "某同學說：『同地點重量較大的物體，慣性一定較大。』要修正這句話，最恰當的是？", {"A": "重量與慣性完全相同，單位也相同", "B": "慣性由速度決定，與質量無關", "C": "重量是重力造成的力；比較慣性應以質量為主要依據", "D": "只要體積大，慣性就一定大"}, "C", "重量是重力作用造成的力，單位為牛頓；慣性大小主要以質量判斷，質量單位為公斤。地球同一地點重量可隨質量增加而增加，但概念不能互換。", "先分辨物理量的定義與單位，再判斷它是否是慣性的直接量度。", ["辨認重量是力，不是物體抗拒改變的名稱。", "重量的單位是牛頓，質量的單位是公斤。", "慣性大小主要跟質量相關。", "同地點重量可反映質量差異，但不能把兩個概念當同義詞。", "所以應選以質量判斷慣性的修正說法。"], "hard"),
    make(9, "兩個大小相同的箱子，一個裝滿書、一個是空箱。若要用相同推力比較它們的慣性，預期哪個箱子的速度改變較小？", {"A": "空箱，因為內部空間較大", "B": "裝滿書的箱子，因為質量較大、慣性較大", "C": "兩者相同，因為外形相同", "D": "無法比較，因為箱子都不能移動"}, "B", "外形相同不代表質量相同；裝滿書的箱子質量通常較大，因此慣性較大，在相同推力與相同作用時間下速度改變較小。", "先排除外形線索，再比較實際質量與同力條件。", ["確認兩箱外形相同，但不要因此判定慣性相同。", "裝書會增加箱子的質量。", "質量較大代表慣性較大。", "相同推力與時間下，大慣性箱子的速度改變較小。", "所以裝滿書的箱子速度改變較小。"], "easy"),
    make(10, "下列哪一項說法最能避免誤用『慣性』？", {"A": "慣性是一種會把物體推出去的力", "B": "物體只在靜止時才有慣性", "C": "慣性是物體維持原有靜止或運動狀態、抗拒改變的性質", "D": "速度越快的物體一定比速度慢的物體慣性大"}, "C", "慣性是物體本身維持原有運動狀態、抗拒改變的性質，不是額外的力；靜止與運動中的物體都具有慣性，大小主要由質量比較。", "看到『慣性』先檢查它是在描述物體性質，還是被錯誤說成一種力。", ["找出敘述是否把慣性當成外加的力。", "慣性其實描述物體抗拒運動狀態改變的性質。", "靜止和運動中的物體都可能具有慣性。", "速度快慢本身不能取代質量作為主要比較依據。", "因此只有把慣性定義為物體性質的敘述正確。"], "medium"),
]

